function fingering(frets){const pressed=frets.map((f,s)=>({f,s})).filter(x=>x.f>0);if(!pressed.length)return{fingers:frets.map(()=>0),barre:null};const min=Math.min(...pressed.map(x=>x.f)),same=pressed.filter(x=>x.f===min);let barre=null;if(same.length>1){const a=same[0].s,b=same.at(-1).s;if(frets.slice(a,b+1).every(f=>f>=min))barre={fret:min,from:a,to:b};}const groups=[];if(barre)groups.push({f:min,strings:same.map(x=>x.s)});for(const x of pressed)if(!barre||x.f!==min)groups.push({f:x.f,strings:[x.s]});groups.sort((a,b)=>a.f-b.f||a.strings[0]-b.strings[0]);if(groups.length>4)return null;const fingers=frets.map(()=>0);groups.forEach((g,i)=>g.strings.forEach(s=>fingers[s]=i+1));return{fingers,barre};}
function shape(notes,bass=notes[0]){const pitches=[...new Set(notes.map(Music.pc))].sort((a,b)=>a-b),root=Music.pc(bass),key=pitches.join(',')+'/'+root;if(cache.has(key))return cache.get(key);let best=null,score=Infinity;const accept=frets=>{const sounding=frets.map((f,s)=>f<0?null:tuning[s]+f).filter(n=>n!==null);if(sounding.length<pitches.length||Math.min(...sounding)%12!==root||!pitches.every(n=>sounding.some(p=>p%12===n)))return;const positive=frets.filter(f=>f>0);if(positive.length&&Math.max(...positive)-Math.min(...positive)>3)return;const fingers=fingering(frets);if(!fingers)return;const muted=frets.filter(f=>f<0).length,first=frets.findIndex(f=>f>=0),last=frets.findLastIndex(f=>f>=0),inside=frets.slice(first,last+1).filter(f=>f<0).length;const cost=(positive.length?Math.max(...positive):0)*1.5+muted*2+inside*8+(positive.length?Math.max(...positive)-Math.min(...positive):0)*2+(fingers.barre?1:0);if(cost<score){score=cost;best={frets:[...frets],...fingers};}};const preset=openShapes[pitches.join(',')];if(preset){accept(preset);if(best){if(pitches.join(',')==='4,7,11'){best.fingers=[0,2,3,0,0,0];best.barre=null;}cache.set(key,best);return best;}}
for(let start=0;start<=12;start++){const choices=tuning.map(n=>[-1,...Array.from({length:4},(_,i)=>start+i).filter(f=>pitches.includes((n+f)%12))]);const search=(s,frets)=>{if(s===6){accept(frets);return;}for(const f of choices[s])search(s+1,[...frets,f]);};search(0,[]);}cache.set(key,best);return best;}
